using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Automation;
using System.Xml.Linq;

public static class FarmManagementTests
{
    private static void Check(bool ok,string label){if(!ok)throw new Exception("Management: "+label);}
    private static FarmGame New(string root){return new FarmGame(Path.Combine(root,"management-"+Guid.NewGuid().ToString("N")+".xml"));}
    private static void Start(FarmGame g){g.S.BlessingOffers=new[]{0,1,3};Check(g.BeginJourney(0,0),"fixture departs");}
    public static string Run(string root)
    {
        var g=New(root);g.S.Xp=Enumerable.Repeat(55,5).ToArray();g.S.ExpeditionClears=Enumerable.Repeat(1,6).ToArray();g.SetPoisonPreset();g.SetCaretaker(1);g.EquipRelic(0,0);g.EquipRelic(5,1);g.S.DisplayPet=2;g.S.DesktopHidden=true;g.S.PetSize=96;g.S.LastFarmTicks=DateTime.UtcNow.AddDays(1).Ticks;
        Check(!g.LoadParty(0)&&!g.SaveParty(-1)&&!g.SaveParty(3),"empty and invalid slots rejected");Check(g.SaveParty(0),"save party");var saved=g.S.SavedParties[0];g.SetPreset(1);g.EquipRelic(3,0);Check(saved.Team.SequenceEqual(new[]{0,4,3})&&saved.Relics.SequenceEqual(new[]{0,5})&&saved.Skills[0]==0,"saved arrays do not alias live configuration");
        int[] xp=(int[])g.S.Xp.Clone();int grain=g.S.Grain;Check(g.LoadParty(0)&&g.S.Team.SequenceEqual(saved.Team)&&g.S.Skills.SequenceEqual(saved.Skills)&&g.S.EquippedRelics.SequenceEqual(saved.Relics)&&g.Caretaker==1,"load restores all configuration parts");Check(g.S.Xp.SequenceEqual(xp)&&g.S.Grain==grain&&g.S.DisplayPet==2&&g.S.DesktopHidden&&g.S.PetSize==96,"load preserves progression resources and display");
        g.AssignPartySlot(0,3);Check(g.S.Team.SequenceEqual(new[]{3,4,0}),"choosing teammate swaps positions");g.AssignPartySlot(1,1);Check(g.S.Team.SequenceEqual(new[]{3,1,0})&&g.Caretaker==4,"joining caretaker assigns departing pet to farm");Check(!g.AssignPartySlot(3,0)&&!g.AssignPartySlot(0,9),"invalid assignment rejected");
        g.S.Grain=g.PartyTrainingCost-1;xp=(int[])g.S.Xp.Clone();grain=g.S.Grain;Check(!g.TrainParty()&&g.S.Grain==grain&&g.S.Xp.SequenceEqual(xp),"insufficient batch training is atomic");g.S.Grain=g.PartyTrainingCost;Check(g.TrainParty()&&g.S.Team.All(p=>g.Level(p)==4)&&g.S.Grain==0&&g.S.Bond==0&&g.S.SeedBond==0,"whole team grows once without bond");g.S.Xp[g.S.Team[0]]=1250;g.S.Grain=1000;int maxed=g.S.Team[0],cost=g.PartyTrainingCost;Check(g.TrainParty()&&g.S.Xp[maxed]==1250&&g.S.Grain==1000-cost,"max-level party member costs nothing");
        Start(g);var team=(int[])g.S.Team.Clone();grain=g.S.Grain;Check(!g.SaveParty(1)&&!g.LoadParty(0)&&!g.AssignPartySlot(0,2)&&!g.TrainParty()&&g.S.Team.SequenceEqual(team)&&g.S.Grain==grain,"active trip locks management changes");g.Retreat();g.Home();
        g.Save();var loaded=new FarmGame(g.SavePath);Check(loaded.S.SavedParties[0].Filled&&loaded.S.SavedParties[0].Team.SequenceEqual(saved.Team)&&loaded.S.JourneyMemories.Length==1,"saved configurations and retreat memory survive reload");
        var advice=New(root);advice.S.Team=new[]{2,1,4};Check(advice.PartyAdvice(0).Contains("雷雨云提供开场潮湿")&&!advice.PartyAdvice(0).Contains("水泡铺潮湿"),"advice names the actual wet source");
        advice.S.Team=new[]{4,1,3};advice.S.Skills[4]=1;Check(advice.PartyAdvice().Contains("赤钳放到种子前面")&&!advice.PartyAdvice(2).Contains("赤钳放到种子前面"),"catalyst advice accounts for order and opening burn blessing");
        advice.S.Team=new[]{1,2,4};advice.S.Skills[2]=1;Check(advice.PartyAdvice().Contains("余热回流")&&!advice.PartyAdvice().Contains("缺少战斗中治疗"),"working heat-recovery combo counts as healing");
        advice.S.Team=new[]{0,2,4};Check(advice.PartyAdvice().Contains("余热回流需要灼烧")&&advice.PartyAdvice(3).Contains("野餐篮补充战后体力")&&!advice.PartyAdvice(2).Contains("缺少战斗中治疗"),"missing burn source and post-battle healing are explained accurately");
        var crops=New(root);crops.S.LastFarmTicks=DateTime.UtcNow.AddDays(1).Ticks;crops.S.Growth=new double[]{11,12,13,14,0,0};Check(crops.PlantingPlan(3)==null&&!crops.ApplyPlanting(3)&&!crops.ApplyPlanting(-1),"locked mint and invalid plans rejected");Check(!crops.ApplyPlanting(0)&&crops.S.Growth[0]==11,"unchanged plan preserves countdowns");Check(crops.ApplyPlanting(1)&&crops.S.Crops.Take(4).SequenceEqual(new[]{0,0,0,1})&&crops.S.Growth.Take(4).SequenceEqual(new double[]{11,12,0,14}),"only changed plots reset");
        crops.S.GardenUnlocked=true;Check(crops.ApplyPlanting(3)&&crops.S.Crops.SequenceEqual(new[]{0,0,1,1,2,2}),"mint plan fills six unlocked plots");var rates=crops.FarmRates();crops.S.Growth=new double[6];crops.S.Berries=crops.S.Grain=crops.S.Mint=0;var now=DateTime.UtcNow;crops.S.LastFarmTicks=now.Ticks;crops.TickFarm(now.AddMinutes(60));int[] actual={crops.S.Berries,crops.S.Grain,crops.S.Mint};for(int i=0;i<3;i++)Check(actual[i]<=rates[i]*60+.001&&rates[i]*60-actual[i]<2*crops.CropYield(i)+.001,"rate forecast agrees with batched harvesting: "+i);
        var history=New(root);history.S.Xp=Enumerable.Repeat(55,5).ToArray();history.SetPoisonPreset();Start(history);history.AdvanceJourney(DateTime.UtcNow.AddHours(2));Check(history.R.Outcome=="victory"&&history.S.JourneyMemories.Length==1&&history.S.JourneyMemories[0].Fertilizer==history.R.RewardFertilizer&&history.S.JourneyMemories[0].Relic==0&&history.R.HistoryRecorded,"victory stores final rewards once");
        var first=history.S.JourneyMemories[0];string names=String.Join("|",first.Names),report=first.Report;history.Save();history.AdvanceJourney(DateTime.UtcNow.AddHours(3));var reread=new FarmGame(history.SavePath);Check(reread.S.JourneyMemories.Length==1,"finished save does not duplicate history");history.Home();history.S.Evolved=true;history.S.SeedStage=3;history.SetPreset(1);Check(String.Join("|",first.Names)==names&&first.Report==report&&first.Levels.All(l=>l==3),"old memory stays unchanged after evolution and loadout changes");
        for(int i=0;i<11;i++){Start(history);history.Retreat();history.Home();}Check(history.S.JourneyMemories.Length==10&&history.S.JourneyMemories.All(m=>m.Outcome=="retreat")&&history.S.JourneyMemories[0].RecordedTicks>=history.S.JourneyMemories[9].RecordedTicks,"only ten newest memories retained");
        var offline=New(root);offline.S.Xp=Enumerable.Repeat(55,5).ToArray();Start(offline);offline.R.NextJourneyTicks=DateTime.UtcNow.AddHours(-1).Ticks;offline.Save();var settled=new FarmGame(offline.SavePath);Check(settled.R.Outcome=="victory"&&settled.S.JourneyMemories.Length==1&&new FarmGame(offline.SavePath).S.JourneyMemories.Length==1,"offline completion records once across restarts");
        var loss=New(root);Start(loss);loss.RouteChoice(0);foreach(int p in loss.S.Team)loss.R.Hp[p]=1;loss.R.Round=2;loss.R.EnemyCount=3;loss.R.EnemyKind=new[]{3,3,3};loss.R.EnemyHp=loss.R.EnemyMax=new[]{1000,1000,1000};loss.Step();Check(loss.R.Outcome=="defeat"&&loss.S.JourneyMemories.Single().Outcome=="defeat","defeat distinct from voluntary retreat");
        var legacy=New(root);legacy.Begin(0,0);legacy.AdoptLegacyJourney();legacy.Retreat();Check(legacy.S.JourneyMemories.Length==0,"legacy mixed-reward trip not invented as new history");
        var xml=XDocument.Load(g.SavePath);xml.Root.Element("SavedParties").Remove();xml.Root.Element("JourneyMemories").Remove();xml.Root.Element("Run").Element("HistoryRecorded").Remove();xml.Root.Element("Run").Element("Withdrew").Remove();string oldPath=Path.Combine(root,"pre-management.xml");xml.Save(oldPath);var migrated=new FarmGame(oldPath);Check(migrated.SavePath==oldPath&&migrated.S.SavedParties.Length==3&&migrated.S.SavedParties.All(p=>!p.Filled)&&migrated.S.JourneyMemories.Length==0&&migrated.S.Xp.SequenceEqual(g.S.Xp),"old saves receive empty new features without rewriting progress");
        g.S.SavedParties[1]=new SavedParty{Filled=true,Team=new[]{99,0,0}};g.S.JourneyMemories=new[]{new JourneyMemory()};g.Save();Check(g.S.SavedParties[0].Filled&&!g.S.SavedParties[1].Filled&&g.S.JourneyMemories.Length==0,"malformed optional records do not discard valid saved parties");
        return "PASS: party snapshot/restore, member swapping and caretaker, atomic team training, active-trip locks, partial planting resets, rate forecast, mint gate, immutable victory/defeat/retreat memories, ten-record limit, offline idempotence and old-save compatibility.";
    }
}

public partial class FarmPanel
{
