    internal void RenderWorkshopChecks(string root)
    {
        Action<bool,string> check=FarmHeadlessTests.Check;G.S.Xp=Enumerable.Repeat(24,5).ToArray();G.S.Grain=120;G.S.GardenUnlocked=true;G.S.ExpeditionClears[0]=1;G.S.LastFarmTicks=DateTime.UtcNow.AddDays(1).Ticks;
        Tab="配队";WorkshopRender(root,"workshop");WorkshopRender(root,"workshop-small",764,571);UIVisible(UIAction("全队升一级 · 麦穗 "+G.PartyTrainingCost),"batch training action visible in minimum workshop");UIVisible(UIAction("去冒险验证搭配"),"departure link visible in minimum workshop");
        var member=UIChildren<ComboBox>((DependencyObject)Content).First(c=>AutomationProperties.GetName(c)=="第 1 位伙伴");member.SelectedIndex=3;WorkshopRender(root,"workshop-swap");check(G.S.Team.SequenceEqual(new[]{3,2,0}),"picker swaps existing party member");
        var skill=UIChildren<ComboBox>((DependencyObject)Content).First(c=>AutomationProperties.GetName(c)==G.Name(0)+"携带技能");skill.SelectedIndex=1;WorkshopRender(root,"workshop-skill");check(G.S.Skills[0]==1,"skill picker changes actual equipped skill");
        UIAction("保存当前").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"workshop-saved");var saved=(int[])G.S.Team.Clone();UIChildren<Expander>((DependencyObject)Content).First(e=>AutomationProperties.GetAutomationId(e)=="workshop-options").IsExpanded=true;WorkshopRender(root,"workshop-options");UIAction("潮露毒种").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"workshop-preset");UIAction("使用").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"workshop-restored");check(G.S.Team.SequenceEqual(saved)&&G.S.Skills[0]==1,"saved party UI restores members and skills");
        UIAction("水雷连锁").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"workshop-overwrite-before");UIAction("覆盖…").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"workshop-overwrite-confirm");check(G.S.SavedParties[0].Team.SequenceEqual(saved),"overwrite waits for explicit confirmation");UIAction("确认覆盖").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"workshop-ready");check(G.S.SavedParties[0].Team.SequenceEqual(G.S.Team),"confirmed overwrite saves the current party");
        int grain=G.S.Grain,cost=G.PartyTrainingCost;UIAction("全队升一级 · 麦穗 "+cost).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"workshop-trained");check(G.S.Team.All(p=>G.Level(p)==3)&&G.S.Grain==grain-cost,"batch training button applies exact cost");
        Tab="农田";plantingOpen=true;selectedPlanting=2;WorkshopRender(root,"planting-before");var crops=(int[])G.S.Crops.Clone();UIAction("多种莓果").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"planting-preview");check(G.S.Crops.SequenceEqual(crops),"preview choice does not replant");int changed=Enumerable.Range(0,G.Plots).Count(i=>G.S.Crops[i]!=G.PlantingPlan(1)[i]);UIAction("应用方案 · 调整 "+changed+" 块田").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"planting-applied");check(G.S.Crops.SequenceEqual(G.PlantingPlan(1)),"apply planting action updates all intended plots");scroller.ScrollToVerticalOffset(245);scroller.UpdateLayout();UIPreview(root,"planting");
        G.S.Xp=Enumerable.Repeat(1250,5).ToArray();G.S.BlessingOffers=new[]{0,1,3};G.BeginJourney(0,0);G.AdvanceJourney(DateTime.UtcNow.AddHours(2));Tab="冒险";WorkshopRender(root,"history-result");UIAction("查看这趟与以往记录").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"history-away");check(Tab=="手册"&&handbookPage==3&&G.S.JourneyMemories.Length==1&&!UIAction("用当前队伍准备这条路线").IsEnabled,"receipt links to history and does not start another trip");
        G.Home();OpenHandbook(3);WorkshopRender(root,"history");var expander=UIChildren<Expander>((DependencyObject)Content).First();expander.IsExpanded=true;UIPreview(root,"history-expanded");UIAction("用当前队伍准备这条路线").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));WorkshopRender(root,"history-route-small",764,571);check(Tab=="冒险"&&G.AtHome&&journeyDifficulty==0&&journeyDepth==0,"history route uses current party and waits at preparation");
        File.WriteAllText(Path.Combine(root,"workshop-ui-regression.txt"),"PASS: minimum-window workshop actions; party/skill pickers; save/use/confirmed overwrite; batch training; planting preview versus application; receipt/history routing; current-party route preparation. Offscreen UI and isolated save only.");
    }
}
